/* Full-scale existing University paintings in the expanded world-space campus. */
import {project} from './city-core.mjs?v=p21-b407-s039-reuse';
export function campusPlacements(m){const origin=m.campus_world.origin;return m.recommended_correction.placements.map(p=>({...p,world_anchor:p.anchor_local_uv.map((n,i)=>n+origin[i]),world_rect:p.footprint_local_xywh.map((n,i)=>i<2?n+origin[i]:n)}));}
export function campusBounds(m,dimensions){const boxes=campusPlacements(m).map(p=>{const q=project(p.world_anchor),s=p.render_scale,d=dimensions.get(p.id);return[q.x-p.anchor_px[0]*s,q.y-p.anchor_px[1]*s,d[0]*s,d[1]*s];});return[Math.min(...boxes.map(b=>b[0]))-40,Math.min(...boxes.map(b=>b[1]))-40,Math.max(...boxes.map(b=>b[0]+b[2]))+40,Math.max(...boxes.map(b=>b[1]+b[3]))+40];}
export async function createUniversityCampus({read,load,loadScenery=load,addSprites}){const path='assets/city-v010/university/',m=await read(path+'placement.json'),rows=campusPlacements(m),dimensions=new Map(),paintings=await Promise.all(rows.map(async p=>{const im=await loadScenery(path+p.file.split('/').pop());dimensions.set(p.id,[im.cwSourceWidth||im.width,im.cwSourceHeight||im.height]);return['campus:'+p.id,im,p.world_anchor,p.anchor_px,p.render_scale,p.world_rect,{universityStreet:true,universityCampus:true,sourceAsset:'campus:'+p.id}];}));const ground=await load(path+'uu_courtyard_patch.webp');addSprites(paintings);let pattern=null;
return {bounds:campusBounds(m,dimensions),report:()=>({placed:true,rect:m.campus_world.rect,origin:m.campus_world.origin,gate:m.public_examine_approach_engine,components:rows.length,gateOpen:false,nativeDoorHeight:65}),drawGround(ctx){const[x,y,w,h]=m.campus_world.rect,pts=[[x-.5,y-.5],[x+w-.5,y-.5],[x+w-.5,y+h-.5],[x-.5,y+h-.5]].map(p=>project(p));if(!pattern){pattern=ctx.createPattern(ground,'repeat');pattern.setTransform(new DOMMatrix([.45,0,0,.45,0,0]));}ctx.save();ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=pattern;ctx.fill();ctx.strokeStyle='#72614a';ctx.lineWidth=4;ctx.stroke();ctx.restore();}};
}
